// Read and parse the existing CSV
const raw = fs.readFileSync(CSV_PATH, "utf-8");
type CsvRow = Record<string, string>;
const rows: CsvRow[] = parse(raw, {
  columns: true,
  skip_empty_lines: true,
  trim: true,
  bom: true,
}) as CsvRow[];

console.log(`Read ${rows.length} rows from ${path.basename(CSV_PATH)}`);

// Build the new row list: for each city, replace venue rows with 8 tiers
const result: CsvRow[] = [];
const processedSlugs = new Set<string>();

// Group non-venue rows by slug for ordering
const nonVenueBySlug = new Map<string, CsvRow[]>();
const venueSample = new Map<string, CsvRow>(); // first venue row per slug (for metadata)

for (const row of rows) {
  const slug = row["slug"];
  if (row["category"].trim().toLowerCase() === "venue") {
    if (!venueSample.has(slug)) venueSample.set(slug, row);
  } else {
    if (!nonVenueBySlug.has(slug)) nonVenueBySlug.set(slug, []);
    nonVenueBySlug.get(slug)!.push(row);
  }
}

// Build ordered slug list (preserving original city order)
const orderedSlugs: string[] = [];
for (const row of rows) {
  if (!orderedSlugs.includes(row["slug"])) orderedSlugs.push(row["slug"]);
}

for (const slug of orderedSlugs) {
  const sample = venueSample.get(slug);
  if (!sample) continue;

  const newTiers = VENUE_DATA[slug];
  if (!newTiers) {
    console.warn(`⚠  No venue data found for slug "${slug}" — skipping venue replacement`);
    continue;
  }

  // Emit 8 new venue rows
  for (const t of newTiers) {
    result.push({
      city: sample["city"],
      state: sample["state"],
      slug: sample["slug"],
      market_type: sample["market_type"],
      peak_season_start: sample["peak_season_start"],
      peak_season_end: sample["peak_season_end"],
      llm_context: "",
      category: "Venue",
      tier_order: String(t.tierOrder),
      tier_name: t.tierName,
      pricing_type: t.pricingType,
      price_low_peak: String(t.priceLowPeak),
      price_high_peak: String(t.priceHighPeak),
      price_low_off_peak: String(t.priceLowOffPeak),
      price_high_off_peak: String(t.priceHighOffPeak),
      blurb: t.blurb,
    });
  }

  // Emit non-venue rows for this city
  const others = nonVenueBySlug.get(slug) ?? [];
  for (const r of others) result.push(r);

  processedSlugs.add(slug);
}

// Write updated CSV
const header = [
  "city","state","slug","market_type","peak_season_start","peak_season_end","llm_context",
  "category","tier_order","tier_name","pricing_type",
  "price_low_peak","price_high_peak","price_low_off_peak","price_high_off_peak","blurb"
];

const lines: string[] = [header.join(",")];
for (const row of result) {
  const cols = header.map((h) => {
    const v = row[h] ?? "";
    // Quote if contains comma, newline, or double quote
    if (v.includes(",") || v.includes("\n") || v.includes('"')) {
      return `"${v.replace(/"/g, '""')}"`;
    }
    return v;
  });
  lines.push(cols.join(","));
}

fs.writeFileSync(CSV_PATH, lines.join("\n"), "utf-8");
console.log(`\n✅ Wrote ${result.length} rows to ${path.basename(CSV_PATH)}`);
console.log(`   Venue tiers per city: 8 (was 6)`);
console.log(`   Total rows: ${result.length} (was ${rows.length})`);
